#!/usr/bin/env python3
"""Validate a the host project assignments document (work split by profile).

Usage: validate_assignments.py <assignments.json> [personas.json]

Checks the shape the Assignments tab renders: every key present with the right
type, item ids unique across the whole document, gates referencing real items,
seams referencing real profiles, and scope paths that are repo-relative. When a
personas file is given, every non-empty `personaId` must resolve to a persona.

Prints `OK` on success; exits non-zero listing every problem found (not just the
first, so one run is enough to fix the document).
"""
import json
import os
import sys

ASSIGNMENT_KEYS = ["personaId", "personaName", "scope", "brief", "items", "seams"]
ITEM_KEYS = ["id", "title", "why", "firstSteps", "specRef", "taskRef", "mandays", "gate"]
SEAM_KEYS = ["with", "contract", "rule"]
GATE_KEYS = ["what", "blocks", "unblockedBy", "approver"]

problems: list[str] = []


def bad(msg: str) -> None:
    problems.append(msg)


def load(path: str, what: str):
    try:
        with open(path, encoding="utf-8") as fh:
            return json.load(fh)
    except FileNotFoundError:
        print(f"ERROR: {what} not found: {path}", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError as exc:
        print(f"ERROR: {what} is not valid JSON: {exc}", file=sys.stderr)
        sys.exit(1)


def check_keys(obj, keys, where: str) -> bool:
    """Exact key set. Returns False when `obj` is not even an object."""
    if not isinstance(obj, dict):
        bad(f"{where} must be an object")
        return False
    for key in keys:
        if key not in obj:
            bad(f"{where} is missing required key '{key}'")
    for key in sorted(set(obj) - set(keys)):
        bad(f"{where} has unexpected key '{key}'")
    return True


def check_str_list(value, where: str) -> None:
    if not isinstance(value, list):
        bad(f"{where} must be an array")
        return
    for i, item in enumerate(value):
        if not isinstance(item, str):
            bad(f"{where}[{i}] must be a string")


def check_scope(value, where: str) -> None:
    check_str_list(value, where)
    if not isinstance(value, list):
        return
    for i, path in enumerate(value):
        if not isinstance(path, str):
            continue
        if path.startswith("/") or ".." in path.replace("\\", "/").split("/"):
            bad(f"{where}[{i}] must be repo-relative without '..': {path!r}")


def main() -> None:
    if len(sys.argv) not in (2, 3):
        print("usage: validate_assignments.py <assignments.json> [personas.json]", file=sys.stderr)
        sys.exit(2)

    doc = load(sys.argv[1], "assignments file")

    persona_ids: set[str] = set()
    if len(sys.argv) == 3 and os.path.exists(sys.argv[2]):
        personas_doc = load(sys.argv[2], "personas file")
        for persona in personas_doc.get("personas", []) or []:
            if isinstance(persona, dict) and isinstance(persona.get("id"), str):
                persona_ids.add(persona["id"])

    if not isinstance(doc, dict):
        print("ERROR: top level must be an object", file=sys.stderr)
        sys.exit(1)
    if not isinstance(doc.get("version"), int):
        bad('"version" must be an integer')
    if not isinstance(doc.get("generatedAt"), str):
        bad('"generatedAt" must be a string (YYYY-MM-DD)')
    check_str_list(doc.get("sources"), '"sources"')
    if not isinstance(doc.get("overlapRisk"), str):
        bad('"overlapRisk" must be a string')

    assignments = doc.get("assignments")
    if not isinstance(assignments, list):
        print('ERROR: "assignments" must be an array', file=sys.stderr)
        sys.exit(1)

    item_ids: set[str] = set()
    profile_names: set[str] = set()

    for a_i, assignment in enumerate(assignments):
        where = f"assignments[{a_i}]"
        if not check_keys(assignment, ASSIGNMENT_KEYS, where):
            continue

        persona_id = assignment.get("personaId")
        if not isinstance(persona_id, str):
            bad(f"{where}.personaId must be a string ('' when no persona fits)")
        elif persona_id and persona_ids and persona_id not in persona_ids:
            bad(f"{where}.personaId '{persona_id}' is not in the personas file")

        name = assignment.get("personaName")
        if not isinstance(name, str) or not name.strip():
            bad(f"{where}.personaName must be a non-empty string")
        else:
            profile_names.add(name)

        if not isinstance(assignment.get("brief"), str):
            bad(f"{where}.brief must be a string")
        check_scope(assignment.get("scope"), f"{where}.scope")

        items = assignment.get("items")
        if not isinstance(items, list):
            bad(f"{where}.items must be an array")
            items = []
        for i_i, item in enumerate(items):
            iwhere = f"{where}.items[{i_i}]"
            if not check_keys(item, ITEM_KEYS, iwhere):
                continue
            item_id = item.get("id")
            if not isinstance(item_id, str) or not item_id.strip():
                bad(f"{iwhere}.id must be a non-empty string")
            elif item_id in item_ids:
                bad(f"{iwhere}.id duplicates an earlier item: {item_id}")
            else:
                item_ids.add(item_id)
            for key in ("title", "why", "specRef", "taskRef", "gate"):
                if not isinstance(item.get(key), str):
                    bad(f"{iwhere}.{key} must be a string")
            if not isinstance(item.get("mandays"), (int, float)) or isinstance(item.get("mandays"), bool):
                bad(f"{iwhere}.mandays must be a number (0 when unknown)")
            check_str_list(item.get("firstSteps"), f"{iwhere}.firstSteps")

        seams = assignment.get("seams")
        if not isinstance(seams, list):
            bad(f"{where}.seams must be an array")
            seams = []
        for s_i, seam in enumerate(seams):
            check_keys(seam, SEAM_KEYS, f"{where}.seams[{s_i}]")

    gates = doc.get("gates")
    if not isinstance(gates, list):
        bad('"gates" must be an array')
        gates = []
    gate_whats: set[str] = set()
    for g_i, gate in enumerate(gates):
        gwhere = f"gates[{g_i}]"
        if not check_keys(gate, GATE_KEYS, gwhere):
            continue
        for key in ("what", "unblockedBy", "approver"):
            if not isinstance(gate.get(key), str):
                bad(f"{gwhere}.{key} must be a string")
        if isinstance(gate.get("what"), str):
            gate_whats.add(gate["what"])
        check_str_list(gate.get("blocks"), f"{gwhere}.blocks")
        for b_i, blocked in enumerate(gate.get("blocks") or []):
            if isinstance(blocked, str) and blocked not in item_ids:
                bad(f"{gwhere}.blocks[{b_i}] references unknown item id '{blocked}'")

    # Cross-references resolved only once every id / name is known.
    for a_i, assignment in enumerate(assignments):
        if not isinstance(assignment, dict):
            continue
        for i_i, item in enumerate(assignment.get("items") or []):
            if isinstance(item, dict):
                gate = item.get("gate")
                if isinstance(gate, str) and gate and gate not in gate_whats:
                    bad(f"assignments[{a_i}].items[{i_i}].gate '{gate}' has no matching entry in gates[]")
        for s_i, seam in enumerate(assignment.get("seams") or []):
            if isinstance(seam, dict):
                other = seam.get("with")
                if isinstance(other, str) and other and other not in profile_names:
                    bad(f"assignments[{a_i}].seams[{s_i}].with '{other}' is not a personaName in this document")

    if problems:
        for problem in problems:
            print(f"ERROR: {problem}", file=sys.stderr)
        sys.exit(1)

    print(f"OK ({len(assignments)} profiles, {len(item_ids)} items, {len(gates)} gates)")


if __name__ == "__main__":
    main()

#!/usr/bin/env node
'use strict';

// change_analyzer.cjs — change verification gate (see ../SKILL.md).
// Self-contained on purpose: skill folders are synced into hosts individually,
// so no cross-skill requires. CommonJS (.cjs) so it runs under any host
// package.json module type.

const { execFileSync } = require('child_process');
const path = require('path');
const fs = require('fs');

// --- shared helpers (inlined; keep in sync across verify-* scripts) ---

function parseCliArgs(argv) {
  const args = argv.slice(2);
  const result = { target: '.', verbose: false, json: false };
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '-v' || args[i] === '--verbose') result.verbose = true;
    else if (args[i] === '--json') result.json = true;
    else if (args[i] === '-h' || args[i] === '--help') result.help = true;
    else if (args[i] === '--mode' && args[i + 1]) result.mode = args[++i];
    else if (!args[i].startsWith('-')) result.target = args[i];
  }
  return result;
}

const SEP = '='.repeat(60);
const DASH = '-'.repeat(40);
const ICONS = { error: '✗', warning: '⚠', info: 'ℹ' };

function buildReport(title, fields, issues, verbose) {
  const lines = [SEP, title, SEP];
  for (const [k, v] of Object.entries(fields)) lines.push(`\n${k}: ${v}`);
  if (issues.length) {
    lines.push('\n' + DASH, 'Issues:', DASH);
    for (const i of issues) {
      lines.push(`  ${ICONS[i.severity] || 'ℹ'} [${i.severity.toUpperCase()}] ${i.message}`);
      if (verbose && i.related_files) {
        for (const f of i.related_files.slice(0, 10)) lines.push(`    - ${f}`);
      }
    }
  }
  lines.push('\n' + SEP);
  return lines.join('\n');
}

// --- analyzer ---

const CODE_EXT = new Set(['.py', '.go', '.rs', '.ts', '.js', '.jsx', '.tsx', '.java', '.c', '.cpp', '.h', '.hpp']);
const DOC_EXT = new Set(['.md', '.rst', '.txt', '.adoc']);
const TEST_PATTERNS = ['test_', '_test.', '.test.', 'spec_', '_spec.', '/tests/', '/test/', '/__tests__/'];
const CONFIG_FILES = new Set(['package.json', 'pyproject.toml', 'go.mod', 'cargo.toml', 'pom.xml', 'makefile', 'dockerfile']);
const CONFIG_EXT = new Set(['.yaml', '.yml', '.json', '.toml', '.ini']);

function normalizePath(p) {
  let s = p.trim();
  if (s.startsWith('"') && s.endsWith('"') && s.length >= 2) {
    s = s.slice(1, -1).replace(/\\"/g, '"').replace(/\\\\/g, '\\');
  }
  if (s.startsWith('./')) s = s.slice(2);
  return s;
}

function classifyFile(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  const name = path.basename(filePath).toLowerCase();
  const lower = filePath.toLowerCase();
  return {
    path: filePath, type: 'modified', additions: 0, deletions: 0,
    is_code: CODE_EXT.has(ext), is_doc: DOC_EXT.has(ext),
    is_test: TEST_PATTERNS.some((p) => lower.includes(p)),
    is_config: CONFIG_FILES.has(name) || CONFIG_EXT.has(ext),
  };
}

function parseNameStatusLine(line) {
  const parts = line.split('\t');
  if (parts.length < 2) return null;
  const status = parts[0][0];
  const p = normalizePath(parts[parts.length - 1]);
  if (!p) return null;
  const c = classifyFile(p);
  const map = { A: 'added', M: 'modified', D: 'deleted', R: 'renamed' };
  if (map[status]) c.type = map[status];
  return c;
}

function parsePorcelainLine(line) {
  if (line.length < 3) return null;
  const status = line.slice(0, 2);
  let raw = line.slice(3);
  if (!raw) return null;
  if (raw.includes(' -> ')) raw = raw.split(' -> ')[1];
  const p = normalizePath(raw);
  if (!p) return null;
  const c = classifyFile(p);
  if (status.includes('?') || status.includes('A')) c.type = 'added';
  else if (status.includes('R')) c.type = 'renamed';
  else if (status.includes('M')) c.type = 'modified';
  else if (status.includes('D')) c.type = 'deleted';
  return c;
}

function git(...args) {
  try { return execFileSync('git', args, { encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'] }); }
  catch { return ''; }
}

function getGitChanges(base = 'HEAD~1', target = 'HEAD') {
  const changes = [];
  for (const line of git('diff', '--name-status', base, target).split('\n')) {
    if (!line) continue;
    const c = parseNameStatusLine(line);
    if (c) changes.push(c);
  }
  const statMap = {};
  for (const line of git('diff', '--numstat', base, target).split('\n')) {
    if (!line) continue;
    const parts = line.split('\t');
    if (parts.length >= 3) {
      statMap[normalizePath(parts[2])] = [
        parts[0] === '-' ? 0 : parseInt(parts[0], 10),
        parts[1] === '-' ? 0 : parseInt(parts[1], 10),
      ];
    }
  }
  for (const c of changes) {
    if (statMap[c.path]) { [c.additions, c.deletions] = statMap[c.path]; }
  }
  return changes;
}

function getStagedChanges() {
  const changes = [];
  for (const line of git('diff', '--cached', '--name-status').split('\n')) {
    if (!line) continue;
    const c = parseNameStatusLine(line);
    if (c) changes.push(c);
  }
  return changes;
}

function getWorkingChanges() {
  const changes = [];
  for (const line of git('status', '--porcelain').split('\n')) {
    if (!line) continue;
    const c = parsePorcelainLine(line);
    if (c) changes.push(c);
  }
  return changes;
}

function isPathInModule(filePath, mod) {
  const np = normalizePath(filePath);
  if (mod === '.') return !np.includes('/');
  return np === mod || np.startsWith(mod + '/');
}

function identifyModules(changes) {
  const modules = new Set();
  for (const c of changes) {
    const np = normalizePath(c.path);
    const parts = np.split('/').filter(Boolean);
    if (parts.length === 1) { modules.add('.'); continue; }
    let found = false;
    for (let i = 0; i < parts.length; i++) {
      const mp = parts.slice(0, i + 1).join('/');
      if (fs.existsSync(path.join(mp, 'README.md')) || fs.existsSync(path.join(mp, 'DESIGN.md'))) {
        modules.add(mp); found = true; break;
      }
    }
    if (!found && parts.length > 1) modules.add(parts[0]);
  }
  return modules;
}

function checkDocSync(changes, modules) {
  const docStatus = {};
  const issues = [];
  const codeChanges = changes.filter((c) => c.is_code && c.type !== 'deleted');
  const docPaths = new Set(changes.filter((c) => c.is_doc).map((c) => normalizePath(c.path)));

  for (const mod of modules) {
    const readme = normalizePath(mod === '.' ? 'README.md' : `${mod}/README.md`);
    const design = normalizePath(mod === '.' ? 'DESIGN.md' : `${mod}/DESIGN.md`);
    const modCode = codeChanges.filter((c) => isPathInModule(c.path, mod));
    if (!modCode.length) continue;
    const total = modCode.reduce((s, c) => s + c.additions + c.deletions, 0);
    if (total > 50 && !docPaths.has(design)) {
      issues.push({
        severity: 'warning',
        message: `Module ${mod} has a large code change (${total} lines) but DESIGN.md was not updated`,
        related_files: modCode.map((c) => c.path),
      });
      docStatus[`${mod}/DESIGN.md`] = false;
    } else {
      docStatus[`${mod}/DESIGN.md`] = true;
    }
    const newFiles = modCode.filter((c) => c.type === 'added');
    if (newFiles.length && !docPaths.has(readme)) {
      issues.push({
        severity: 'info',
        message: `Module ${mod} gained new files — consider updating README.md`,
        related_files: newFiles.map((c) => c.path),
      });
    }
  }
  return { docStatus, issues };
}

function analyzeImpact(changes) {
  const issues = [];
  const code = changes.filter((c) => c.is_code && !c.is_test);
  const tests = changes.filter((c) => c.is_test);
  if (code.length && !tests.length) {
    const total = code.reduce((s, c) => s + c.additions + c.deletions, 0);
    if (total > 30) {
      issues.push({
        severity: 'warning',
        message: `${total} lines of code changed without a matching test update`,
        related_files: code.map((c) => c.path),
      });
    }
  }
  const configs = changes.filter((c) => c.is_config);
  if (configs.length) {
    issues.push({
      severity: 'info',
      message: 'Config files changed — confirm whether docs need an update',
      related_files: configs.map((c) => c.path),
    });
  }
  const deleted = changes.filter((c) => c.type === 'deleted');
  if (deleted.length) {
    issues.push({
      severity: 'info',
      message: `${deleted.length} file(s) deleted — confirm references are cleaned up`,
      related_files: deleted.map((c) => c.path),
    });
  }
  return issues;
}

function analyzeChanges(mode = 'working') {
  let changes;
  if (mode === 'staged') changes = getStagedChanges();
  else if (mode === 'committed') changes = getGitChanges();
  else changes = getWorkingChanges();

  const issues = [];
  let modules = new Set();
  let docStatus = {};
  if (changes.length) {
    modules = identifyModules(changes);
    const ds = checkDocSync(changes, modules);
    docStatus = ds.docStatus;
    issues.push(...ds.issues, ...analyzeImpact(changes));
  }
  const passed = !issues.some((i) => i.severity === 'error');
  const totalAdd = changes.reduce((s, c) => s + c.additions, 0);
  const totalDel = changes.reduce((s, c) => s + c.deletions, 0);
  return { changes, issues, modules, docStatus, passed, totalAdd, totalDel };
}

function formatReport(r, verbose) {
  const fields = {
    'Files changed': r.changes.length,
    'Lines added': `+${r.totalAdd}`,
    'Lines deleted': `-${r.totalDel}`,
    'Affected modules': [...r.modules].join(', ') || 'none',
    'Result': r.passed ? '✓ pass' : '✗ needs attention',
  };
  let report = buildReport('Change Analysis Report', fields, r.issues, verbose);

  if (r.changes.length && verbose) {
    const lines = ['\n' + DASH, 'Changed files:', DASH];
    const icons = { added: '➕', modified: '📝', deleted: '➖', renamed: '📋' };
    for (const c of r.changes) {
      const tags = [];
      if (c.is_code) tags.push('code');
      if (c.is_doc) tags.push('doc');
      if (c.is_test) tags.push('test');
      if (c.is_config) tags.push('config');
      const t = tags.length ? ` [${tags.join(', ')}]` : '';
      lines.push(`  ${icons[c.type] || '📝'} ${c.path}${t} (+${c.additions}/-${c.deletions})`);
    }
    report += '\n' + lines.join('\n');
  }

  if (Object.keys(r.docStatus).length) {
    const lines = ['\n' + DASH, 'Doc sync status:', DASH];
    for (const [doc, synced] of Object.entries(r.docStatus)) {
      lines.push(`  ${synced ? '✓' : '✗'} ${doc}`);
    }
    report += '\n' + lines.join('\n');
  }

  return report;
}

// CLI
if (require.main === module) {
  const opts = parseCliArgs(process.argv);
  const result = analyzeChanges(opts.mode || 'working');

  if (opts.json) {
    console.log(JSON.stringify({
      passed: result.passed,
      total_additions: result.totalAdd,
      total_deletions: result.totalDel,
      affected_modules: [...result.modules],
      changes: result.changes.map((c) => ({
        path: c.path, type: c.type, additions: c.additions,
        deletions: c.deletions, is_code: c.is_code,
        is_doc: c.is_doc, is_test: c.is_test,
      })),
      issues: result.issues.map((i) => ({
        severity: i.severity, message: i.message,
        related_files: i.related_files,
      })),
      doc_sync_status: result.docStatus,
    }, null, 2));
  } else {
    console.log(formatReport(result, opts.verbose));
  }

  process.exit(result.passed ? 0 : 1);
}

module.exports = { normalizePath, classifyFile, parsePorcelainLine, parseNameStatusLine, identifyModules };

#!/usr/bin/env node
'use strict';

// module_scanner.cjs — module completeness gate (see ../SKILL.md).
// Self-contained on purpose: skill folders are synced into hosts individually,
// so no cross-skill requires. CommonJS (.cjs) so it runs under any host
// package.json module type.

const fs = require('fs');
const path = require('path');

// --- shared helpers (inlined; keep in sync across verify-* scripts) ---

function parseCliArgs(argv) {
  const args = argv.slice(2);
  const result = { target: '.', verbose: false, json: false };
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '-v' || args[i] === '--verbose') result.verbose = true;
    else if (args[i] === '--json') result.json = true;
    else if (args[i] === '-h' || args[i] === '--help') result.help = true;
    else if (args[i] === '--mode' && args[i + 1]) result.mode = args[++i];
    else if (args[i] === '--exclude') {
      result.exclude = result.exclude || [];
      while (i + 1 < args.length && !args[i + 1].startsWith('-')) result.exclude.push(args[++i]);
    } else if (!args[i].startsWith('-')) result.target = args[i];
  }
  return result;
}

const SEP = '='.repeat(60);
const ICONS = {
  error: '✗', warning: '⚠', info: 'ℹ',
  critical: '\u{1F534}', high: '\u{1F7E0}', medium: '\u{1F7E1}', low: '\u{1F535}',
};

function buildReport(title, fields, issues, verbose) {
  const lines = [SEP, title, SEP];
  for (const [k, v] of Object.entries(fields)) lines.push(`\n${k}: ${v}`);
  if (issues.length) {
    lines.push('\n' + '-'.repeat(40), 'Issues:', '-'.repeat(40));
    for (const i of issues) {
      lines.push(`  ${ICONS[i.severity] || 'ℹ'} [${i.severity.toUpperCase()}] ${i.message}`);
      if (i.path && verbose) lines.push(`    path: ${i.path}`);
    }
  }
  lines.push('\n' + SEP);
  return lines.join('\n');
}

function hasFatal(issues, fatalLevels) {
  const levels = fatalLevels || ['error'];
  return issues.some((i) => levels.includes(i.severity));
}

// --- scanner ---

const REQUIRED_FILES = { 'README.md': 'module documentation', 'DESIGN.md': 'design-decision record' };
const ALT_SRC_DIRS = ['src', 'lib', 'pkg', 'internal', 'cmd', 'app'];
const ALT_TEST_DIRS = ['tests', 'test', '__tests__', 'spec'];
const ROOT_SCRIPT_FILES = new Set([
  'install.sh', 'uninstall.sh', 'install.ps1',
  'uninstall.ps1', 'Dockerfile', 'Makefile',
]);
const CODE_EXTS = new Set(['.py', '.go', '.rs', '.ts', '.js', '.java', '.sh', '.ps1']);
const TEST_PATTERNS = ['test_', '_test.', '.test.', 'spec_', '_spec.'];

function scanStructure(p, depth = 3) {
  const s = { name: path.basename(p), type: 'dir', children: [] };
  if (depth <= 0) return s;
  try {
    for (const name of fs.readdirSync(p).sort()) {
      if (name.startsWith('.')) continue;
      const full = path.join(p, name);
      const stat = fs.statSync(full);
      if (stat.isFile()) s.children.push({ name, type: 'file', size: stat.size });
      else if (stat.isDirectory()) s.children.push(scanStructure(full, depth - 1));
    }
  } catch {}
  return s;
}

function rglob(dir, test) {
  try {
    for (const name of fs.readdirSync(dir)) {
      const full = path.join(dir, name);
      try {
        const stat = fs.statSync(full);
        if (stat.isFile() && test(name)) return true;
        if (stat.isDirectory()) { if (rglob(full, test)) return true; }
      } catch {}
    }
  } catch {}
  return false;
}

function scanModule(target) {
  const modulePath = path.resolve(target);
  const issues = [];
  const add = (severity, message, p) => issues.push({ severity, message, path: p || null });

  if (!fs.existsSync(modulePath)) {
    add('error', `Path does not exist: ${modulePath}`);
    return { modulePath, issues, structure: {} };
  }
  if (!fs.statSync(modulePath).isDirectory()) {
    add('error', `Not a directory: ${modulePath}`);
    return { modulePath, issues, structure: {} };
  }

  const structure = scanStructure(modulePath);

  // required files
  for (const [file, desc] of Object.entries(REQUIRED_FILES)) {
    const fp = path.join(modulePath, file);
    if (!fs.existsSync(fp)) add('error', `Missing required doc: ${file} (${desc})`, fp);
    else if (fs.statSync(fp).size < 50) add('warning', `Doc nearly empty: ${file} (< 50 bytes)`, fp);
  }

  // source dirs
  let srcFound = ALT_SRC_DIRS.some((d) => {
    try { return fs.statSync(path.join(modulePath, d)).isDirectory(); }
    catch { return false; }
  });
  const entries = fs.readdirSync(modulePath);
  const rootCode = entries.filter((n) => {
    try {
      const s = fs.statSync(path.join(modulePath, n));
      return s.isFile() && CODE_EXTS.has(path.extname(n));
    } catch { return false; }
  });
  const rootScript = entries.filter((n) => {
    try {
      return fs.statSync(path.join(modulePath, n)).isFile()
        && ROOT_SCRIPT_FILES.has(n);
    } catch { return false; }
  });
  if (rootCode.length || rootScript.length) {
    srcFound = true;
    if (rootCode.length > 5) {
      add('warning', `Too many code files at module root (${rootCode.length}) — consider moving them into src/`);
    }
  }
  if (!srcFound) add('warning', 'No source directory or code files found');

  // test dirs
  let testFound = ALT_TEST_DIRS.some((d) => {
    try { return fs.statSync(path.join(modulePath, d)).isDirectory(); }
    catch { return false; }
  });
  if (!testFound) testFound = rglob(modulePath, (n) => TEST_PATTERNS.some((p) => n.includes(p)));
  if (!testFound) add('warning', 'No test directory or test files found');

  // doc quality
  const readme = path.join(modulePath, 'README.md');
  if (fs.existsSync(readme)) {
    const c = fs.readFileSync(readme, 'utf-8');
    if (!c.includes('#')) add('warning', 'README.md has no heading', readme);
    const docKeys = ['usage', 'install', 'example', 'quick start', 'getting started'];
    if (!docKeys.some((k) => c.toLowerCase().includes(k)))
      add('info', 'README.md should include usage notes or an example', readme);
  }
  const design = path.join(modulePath, 'DESIGN.md');
  if (fs.existsSync(design)) {
    const c = fs.readFileSync(design, 'utf-8');
    const designKeys = ['decision', 'choice', 'trade', 'alternative', 'rationale'];
    if (!designKeys.some((k) => c.toLowerCase().includes(k)))
      add('info', 'DESIGN.md should record design decisions and trade-offs', design);
  }

  return { modulePath, issues, structure };
}

function formatStructure(s, indent = 0) {
  const pre = '  '.repeat(indent);
  if (s.type === 'dir') {
    const lines = [`${pre}\u{1F4C1} ${s.name}/`];
    for (const ch of (s.children || [])) lines.push(formatStructure(ch, indent + 1));
    return lines.join('\n');
  }
  const sz = (s.size || 0) < 1024 ? `(${s.size} B)` : `(${Math.floor(s.size / 1024)} KB)`;
  return `${pre}\u{1F4C4} ${s.name} ${sz}`;
}

function formatReport(r, verbose) {
  const errs = r.issues.filter((i) => i.severity === 'error').length;
  const warns = r.issues.filter((i) => i.severity === 'warning').length;
  const passed = !hasFatal(r.issues);
  const fields = {
    'Module path': r.modulePath,
    'Result': passed ? '✓ pass' : '✗ fail',
    'Counts': `errors: ${errs} | warnings: ${warns}`,
  };
  let report = buildReport('Module Completeness Report', fields, r.issues, verbose);
  if (verbose && r.structure.name) {
    report += '\n' + '-'.repeat(40) + '\nStructure:\n' + '-'.repeat(40) + '\n' + formatStructure(r.structure);
  }
  return report;
}

// CLI
const opts = parseCliArgs(process.argv);
const result = scanModule(opts.target);
const passed = !hasFatal(result.issues);

if (opts.json) {
  console.log(JSON.stringify({
    module_path: result.modulePath, passed,
    error_count: result.issues.filter((i) => i.severity === 'error').length,
    warning_count: result.issues.filter((i) => i.severity === 'warning').length,
    issues: result.issues,
  }, null, 2));
} else {
  console.log(formatReport(result, opts.verbose));
}

process.exit(passed ? 0 : 1);

#!/usr/bin/env node
'use strict';

// quality_checker.cjs — code quality gate (see ../SKILL.md).
// Self-contained on purpose: skill folders are synced into hosts individually,
// so no cross-skill requires. CommonJS (.cjs) so it runs under any host
// package.json module type.

const fs = require('fs');
const path = require('path');

// --- shared helpers (inlined; keep in sync across verify-* scripts) ---

function parseCliArgs(argv) {
  const args = argv.slice(2);
  const result = { target: '.', verbose: false, json: false };
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '-v' || args[i] === '--verbose') result.verbose = true;
    else if (args[i] === '--json') result.json = true;
    else if (args[i] === '-h' || args[i] === '--help') result.help = true;
    else if (!args[i].startsWith('-')) result.target = args[i];
  }
  return result;
}

const SEP = '='.repeat(60);
const DASH = '-'.repeat(40);
const ICONS = { error: '✗', warning: '⚠', info: 'ℹ' };

function buildReport(title, fields, issues, verbose, groupBy) {
  const lines = [SEP, title, SEP];
  for (const [k, v] of Object.entries(fields)) lines.push(`\n${k}: ${v}`);
  if (issues.length) {
    lines.push('\n' + DASH, 'Issues:', DASH);
    if (groupBy) {
      const groups = {};
      for (const i of issues) (groups[i[groupBy]] || (groups[i[groupBy]] = [])).push(i);
      for (const cat of Object.keys(groups).sort()) {
        const items = groups[cat];
        lines.push(`\n[${cat}] (${items.length})`);
        for (const i of items.slice(0, 10)) {
          lines.push(`  ${ICONS[i.severity] || 'ℹ'} ${i.file_path || ''}${i.line_number ? ':' + i.line_number : ''}`);
          lines.push(`    ${i.message}`);
          if (verbose && i.suggestion) lines.push(`    💡 ${i.suggestion}`);
        }
        if (items.length > 10) lines.push(`  ... and ${items.length - 10} more`);
      }
    } else {
      for (const i of issues) lines.push(`  ${ICONS[i.severity] || 'ℹ'} [${i.severity.toUpperCase()}] ${i.message}`);
    }
  }
  lines.push('\n' + SEP);
  return lines.join('\n');
}

function hasFatal(issues, fatalLevels) {
  const levels = fatalLevels || ['error'];
  return issues.some((i) => levels.includes(i.severity));
}

// --- quality rules ---

const MAX_LINE_LENGTH = 120;
const MAX_FUNCTION_LENGTH = 50;
const MAX_FILE_LENGTH = 500;
const MAX_COMPLEXITY = 10;
const MAX_PARAMETERS = 5;
const MIN_FUNCTION_NAME_LENGTH = 2;

const EXCLUDE_DIRS = new Set(['.git', 'node_modules', '__pycache__', '.venv', 'venv', 'dist', 'build', '.tox']);
const CODE_EXTENSIONS = new Set(['.py', '.js', '.cjs', '.mjs', '.ts', '.go', '.java', '.rs', '.c', '.cpp']);

const COMMENT_PREFIXES = {
  '.js': '//', '.cjs': '//', '.mjs': '//', '.ts': '//', '.go': '//', '.java': '//',
  '.c': '//', '.cpp': '//', '.rs': '//',
};

// --- Analysis ---

function analyzeGenericFile(filePath) {
  const metrics = {
    path: filePath, lines: 0, code_lines: 0, comment_lines: 0,
    blank_lines: 0, functions: 0, classes: 0,
    max_complexity: 0, avg_function_length: 0,
  };
  const issues = [];
  let content;
  try {
    content = fs.readFileSync(filePath, 'utf-8');
  } catch { return { metrics, issues }; }

  const lines = content.split('\n');
  metrics.lines = lines.length;
  const prefix = COMMENT_PREFIXES[
    path.extname(filePath).toLowerCase()
  ] || '//';

  for (let i = 0; i < lines.length; i++) {
    const stripped = lines[i].trim();
    if (!stripped) metrics.blank_lines++;
    else if (
      stripped.startsWith(prefix) ||
      stripped.startsWith('/*') ||
      stripped.startsWith('*')
    ) metrics.comment_lines++;
    else metrics.code_lines++;

    if (lines[i].length > MAX_LINE_LENGTH) {
      issues.push({
        severity: 'info', category: 'format',
        message: `Line too long (${lines[i].length} > ${MAX_LINE_LENGTH})`,
        file_path: filePath, line_number: i + 1,
        suggestion: null,
      });
    }
  }

  if (metrics.code_lines > MAX_FILE_LENGTH) {
    issues.push({
      severity: 'warning', category: 'complexity',
      message: `File too long (${metrics.code_lines} code lines > ${MAX_FILE_LENGTH})`,
      file_path: filePath, suggestion: 'Consider splitting into multiple modules',
      line_number: null,
    });
  }

  return { metrics, issues };
}

function analyzePythonFile(filePath) {
  const metrics = {
    path: filePath, lines: 0, code_lines: 0, comment_lines: 0,
    blank_lines: 0, functions: 0, classes: 0,
    max_complexity: 0, avg_function_length: 0,
  };
  const issues = [];
  let content;
  try {
    content = fs.readFileSync(filePath, 'utf-8');
  } catch (e) {
    issues.push({
      severity: 'error', category: 'file',
      message: `Cannot read file: ${e.message}`,
      file_path: filePath, line_number: null, suggestion: null,
    });
    return { metrics, issues };
  }

  const lines = content.split('\n');
  metrics.lines = lines.length;
  let inMultiline = false;

  for (let i = 0; i < lines.length; i++) {
    const stripped = lines[i].trim();
    if (!stripped) { metrics.blank_lines++; }
    else if (stripped.startsWith('#')) { metrics.comment_lines++; }
    else if (stripped.includes('"""') || stripped.includes("'''")) {
      const dq = (stripped.match(/"""/g) || []).length;
      const sq = (stripped.match(/'''/g) || []).length;
      if (dq === 2 || sq === 2) { metrics.comment_lines++; }
      else { inMultiline = !inMultiline; metrics.comment_lines++; }
    } else if (inMultiline) { metrics.comment_lines++; }
    else { metrics.code_lines++; }

    if (lines[i].length > MAX_LINE_LENGTH) {
      issues.push({
        severity: 'info', category: 'format',
        message: `Line too long (${lines[i].length} > ${MAX_LINE_LENGTH})`,
        file_path: filePath, line_number: i + 1,
        suggestion: null,
      });
    }
  }

  if (metrics.code_lines > MAX_FILE_LENGTH) {
    issues.push({
      severity: 'warning', category: 'complexity',
      message: `File too long (${metrics.code_lines} code lines > ${MAX_FILE_LENGTH})`,
      file_path: filePath, suggestion: 'Consider splitting into multiple modules',
      line_number: null,
    });
  }

  // Regex-based Python analysis (no AST available in Node)
  const funcRegex = /^( *)(?:async\s+)?def\s+(\w+)\s*\(([^)]*)\)/gm;
  const classRegex = /^( *)class\s+(\w+)/gm;
  const functions = [];
  let match;

  while ((match = funcRegex.exec(content)) !== null) {
    const lineNum = content.substring(0, match.index).split('\n').length;
    const name = match[2];
    const indent = match[1].length;
    const params = match[3].trim()
      ? match[3].split(',').map(p => p.trim())
        .filter(p => p && p !== 'self' && p !== 'cls')
      : [];

    // Calculate function length by finding next line at same or lesser indent
    const funcLines = lines.slice(lineNum); // lines after def
    let length = 1;
    for (let j = 1; j < funcLines.length; j++) {
      const l = funcLines[j];
      if (l.trim() === '') { length++; continue; }
      const curIndent = l.match(/^(\s*)/)[1].length;
      if (curIndent <= indent && l.trim() !== '') break;
      length++;
    }

    // Estimate complexity from function body
    const bodyLines = lines.slice(lineNum, lineNum + length - 1);
    let complexity = 1;
    for (const bl of bodyLines) {
      const s = bl.trim();
      if (/^(if|elif|while|for)\s/.test(s) || /^(if|elif|while|for)\(/.test(s)) complexity++;
      if (/^except(\s|:)/.test(s)) complexity++;
      if (/\s(and|or)\s/.test(s)) complexity++;
      if (/\sfor\s/.test(s) && /\sin\s/.test(s) && (s.includes('[') || s.includes('('))) complexity++;
    }

    functions.push({ name, line: lineNum, length, complexity, parameters: params.length });
    metrics.max_complexity = Math.max(metrics.max_complexity, complexity);

    // Check function length
    if (length > MAX_FUNCTION_LENGTH) {
      issues.push({
        severity: 'warning', category: 'complexity',
        message: `Function '${name}' too long (${length} lines > ${MAX_FUNCTION_LENGTH})`,
        file_path: filePath, line_number: lineNum,
        suggestion: 'Consider splitting into smaller functions',
      });
    }
    // Check complexity
    if (complexity > MAX_COMPLEXITY) {
      issues.push({
        severity: 'warning', category: 'complexity',
        message: `Function '${name}' cyclomatic complexity too high (${complexity} > ${MAX_COMPLEXITY})`,
        file_path: filePath, line_number: lineNum,
        suggestion: 'Reduce nesting; extract helper functions',
      });
    }
    // Check parameter count
    if (params.length > MAX_PARAMETERS) {
      issues.push({
        severity: 'warning', category: 'design',
        message: `Function '${name}' has too many parameters (${params.length} > ${MAX_PARAMETERS})`,
        file_path: filePath, line_number: lineNum,
        suggestion: 'Consider an options object or dataclass',
      });
    }
    // Check naming
    const SPECIAL = new Set([
      'setUp', 'tearDown', 'setUpClass',
      'tearDownClass', 'setUpModule', 'tearDownModule',
    ]);
    if (!name.startsWith('_') && !SPECIAL.has(name) && !name.startsWith('visit_')) {
      if (!/^[a-z][a-z0-9_]*$/.test(name)) {
        issues.push({
          severity: 'info', category: 'naming',
          message: `Function name '${name}' is not snake_case`,
          file_path: filePath, line_number: lineNum,
          suggestion: 'Use snake_case for function names',
        });
      }
    }
    if (name.length < MIN_FUNCTION_NAME_LENGTH) {
      issues.push({
        severity: 'warning', category: 'naming',
        message: `Function name '${name}' too short`,
        file_path: filePath, line_number: lineNum,
        suggestion: 'Use a more descriptive function name',
      });
    }
  }

  while ((match = classRegex.exec(content)) !== null) {
    const lineNum = content.substring(0, match.index).split('\n').length;
    const name = match[2];
    metrics.classes++;
    if (!/^[A-Z][a-zA-Z0-9]*$/.test(name)) {
      issues.push({
        severity: 'warning', category: 'naming',
        message: `Class name '${name}' is not PascalCase`,
        file_path: filePath, line_number: lineNum,
        suggestion: 'Use PascalCase for class names, e.g. MyClassName',
      });
    }
  }

  metrics.functions = functions.length;
  if (functions.length > 0) {
    metrics.avg_function_length = functions.reduce((s, f) => s + f.length, 0) / functions.length;
  }

  return { metrics, issues };
}

// --- Directory scan ---

function scanDirectory(scanPath, excludeDirs) {
  const resolved = path.resolve(scanPath);
  const exclude = excludeDirs || EXCLUDE_DIRS;
  const result = {
    scan_path: resolved, files_scanned: 0,
    total_lines: 0, total_code_lines: 0,
    issues: [], file_metrics: [],
  };

  function walk(dir) {
    let entries;
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      if (exclude.has(entry.name)) continue;
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) { walk(full); continue; }
      const ext = path.extname(entry.name).toLowerCase();
      if (!CODE_EXTENSIONS.has(ext)) continue;

      result.files_scanned++;
      const { metrics, issues } = ext === '.py' ? analyzePythonFile(full) : analyzeGenericFile(full);
      result.file_metrics.push(metrics);
      result.issues.push(...issues);
      result.total_lines += metrics.lines;
      result.total_code_lines += metrics.code_lines;
    }
  }

  walk(resolved);
  return result;
}

// --- Reporting ---

function passed(result) { return !hasFatal(result.issues); }

function formatReport(result, verbose) {
  const errs = result.issues.filter(i => i.severity === 'error').length;
  const warns = result.issues.filter(i => i.severity === 'warning').length;
  const fields = {
    'Scan path': result.scan_path,
    'Files scanned': result.files_scanned,
    'Total lines': result.total_lines,
    'Code lines': result.total_code_lines,
    'Result': passed(result) ? '✓ pass' : '✗ needs attention',
    'Counts': `errors: ${errs} | warnings: ${warns}`,
  };
  let report = buildReport(
    'Code Quality Report', fields, result.issues, verbose, 'category'
  );

  if (verbose && result.file_metrics.length) {
    const complex = result.file_metrics
      .filter(m => m.max_complexity > 0)
      .sort((a, b) => b.max_complexity - a.max_complexity)
      .slice(0, 5);
    if (complex.length) {
      const lines = ['\n' + DASH, 'Most complex files:', DASH];
      for (const m of complex) lines.push(`  ${m.path}: complexity ${m.max_complexity}, ${m.functions} function(s)`);
      report += '\n' + lines.join('\n');
    }
  }
  return report;
}

// --- CLI ---

function main() {
  const opts = parseCliArgs(process.argv);

  const result = scanDirectory(opts.target);

  if (opts.json) {
    const output = {
      scan_path: result.scan_path,
      files_scanned: result.files_scanned,
      total_lines: result.total_lines,
      total_code_lines: result.total_code_lines,
      passed: passed(result),
      error_count: result.issues.filter(i => i.severity === 'error').length,
      warning_count: result.issues.filter(i => i.severity === 'warning').length,
      issues: result.issues
    };
    console.log(JSON.stringify(output, null, 2));
  } else {
    console.log(formatReport(result, opts.verbose));
  }

  process.exit(passed(result) ? 0 : 1);
}

main();

#!/usr/bin/env node
'use strict';

// security_scanner.cjs — security verification gate (see ../SKILL.md).
// Self-contained on purpose: skill folders are synced into hosts individually,
// so no cross-skill requires. CommonJS (.cjs) so it runs under any host
// package.json module type.

const fs = require('fs');
const path = require('path');

const SEVERITY_ORDER = { critical: 0, high: 1, medium: 2, low: 3, info: 4 };

// prettier-ignore
const SECURITY_RULES = [
  {
    id: 'SQL_INJECTION_DYNAMIC', category: 'injection',
    severity: 'critical',
    pattern: new RegExp(
      '\\b(execute|query|raw)\\s*\\(\\s*' +
      '(f["\']|["\'][^"\'\\n]*["\']\\s*\\+\\s*|["\'][^"\'\\n]*["\']\\s*%\\s*[^,)]|["\'][^"\'\\n]*["\']' +
      '\\.format\\s*\\()', 'i'),
    extensions: ['.py', '.js', '.ts', '.go', '.java', '.php'],
    message: 'Possible SQL injection',
    recommendation: 'Use parameterized queries or an ORM',
  },
  {
    id: 'SQL_INJECTION_FSTRING', category: 'injection',
    severity: 'critical',
    pattern: /cursor\.(execute|executemany)\s*\(\s*f["']/i,
    extensions: ['.py'],
    message: 'SQL statement built with an f-string',
    recommendation: 'Use parameterized queries',
  },
  {
    id: 'COMMAND_INJECTION', category: 'injection',
    severity: 'critical',
    pattern: /(os\.system|os\.popen|subprocess\.call|subprocess\.run|subprocess\.Popen)\s*\([^)]*shell\s*=\s*True/i,
    extensions: ['.py'],
    message: 'shell=True can allow command injection',
    recommendation: 'Avoid shell=True; pass arguments as a list',
  },
  {
    id: 'COMMAND_INJECTION_EVAL', category: 'injection',
    severity: 'critical',
    pattern: /\b(eval|exec)\s*\([^)]*\b(input|request|argv|args)/i,
    extensions: ['.py'],
    message: 'eval/exec on user input',
    recommendation: 'Never eval/exec user input',
  },
  {
    id: 'HARDCODED_SECRET', category: 'secrets',
    severity: 'high',
    pattern: /(?<!\w)(password|passwd|pwd|secret|api_key|apikey|token|auth_token)\s*=\s*["'][^"']{8,}["']/i,
    excludePattern: /(example|placeholder|changeme|xxx|your[_-]|TODO|FIXME|<.*>|\*{3,})/i,
    extensions: [
      '.py', '.js', '.ts', '.go', '.java', '.php',
      '.rb', '.yaml', '.yml', '.json', '.env',
    ],
    message: 'Possible hardcoded secret/password',
    recommendation: 'Use environment variables or a secret manager',
  },
  {
    id: 'HARDCODED_AWS_KEY', category: 'secrets',
    severity: 'critical',
    pattern: /AKIA[0-9A-Z]{16}/,
    extensions: ['*'],
    message: 'AWS access key found',
    recommendation: 'Rotate the key immediately; use IAM roles or environment variables',
  },
  {
    id: 'HARDCODED_PRIVATE_KEY', category: 'secrets',
    severity: 'critical',
    pattern: /-----BEGIN (RSA |EC |DSA |OPENSSH )?PRIVATE KEY-----/,
    extensions: ['*'],
    message: 'Private key found',
    recommendation: 'Private keys must not be committed to the repository',
  },
  {
    id: 'XSS_INNERHTML', category: 'xss', severity: 'high',
    pattern: /\.innerHTML\s*=|\.outerHTML\s*=|document\.write\s*\(/i,
    extensions: ['.js', '.ts', '.jsx', '.tsx', '.html'],
    message: 'Direct innerHTML manipulation can allow XSS',
    recommendation: 'Use textContent or your framework\'s safe binding',
  },
  {
    id: 'XSS_DANGEROUSLY', category: 'xss',
    severity: 'medium',
    pattern: /dangerouslySetInnerHTML/i,
    extensions: ['.js', '.ts', '.jsx', '.tsx'],
    message: 'dangerouslySetInnerHTML in use',
    recommendation: 'Ensure the content is sanitized first',
  },
  {
    id: 'UNSAFE_PICKLE', category: 'deserialization',
    severity: 'high',
    pattern: /pickle\.loads?\s*\(|yaml\.load\s*\([^)]*Loader\s*=\s*yaml\.Loader/i,
    extensions: ['.py'],
    message: 'Unsafe deserialization',
    recommendation: 'Use yaml.safe_load() or validate the data source',
  },
  {
    id: 'WEAK_CRYPTO_MD5', category: 'crypto',
    severity: 'medium',
    pattern: /\b(md5|MD5)\s*\(|hashlib\.md5\s*\(/i,
    extensions: ['.py', '.js', '.ts', '.go', '.java', '.php'],
    message: 'Weak hash algorithm (MD5)',
    recommendation: 'Use bcrypt/argon2 for passwords, or SHA-256+',
  },
  {
    id: 'WEAK_CRYPTO_SHA1', category: 'crypto',
    severity: 'low',
    pattern: /\b(sha1|SHA1)\s*\(|hashlib\.sha1\s*\(/i,
    extensions: ['.py', '.js', '.ts', '.go', '.java', '.php'],
    message: 'Weak hash algorithm (SHA1)',
    recommendation: 'Use SHA-256 or stronger',
  },
  {
    id: 'PATH_TRAVERSAL', category: 'path-traversal',
    severity: 'high',
    pattern: new RegExp(
      '(open|read|write|Path|os\\.path\\.join)\\s*\\([^\\n]*' +
      '(request|input|argv|args|params|query|form|path_param)\\b', 'i'),
    extensions: ['.py'],
    message: 'Possible path traversal',
    recommendation: 'Validate and normalize user-supplied paths',
  },
  {
    id: 'SSRF', category: 'ssrf', severity: 'high',
    pattern: new RegExp(
      '(requests\\.(get|post|put|delete|head)|urllib\\.request\\.urlopen)' +
      '\\s*\\([^\\n]*(request|input|argv|args|params|query|url)\\b', 'i'),
    extensions: ['.py'],
    message: 'Possible SSRF',
    recommendation: 'Validate and restrict target URLs',
  },
  {
    id: 'DEBUG_CODE', category: 'debug', severity: 'low',
    pattern: /\b(console\.log|debugger|pdb\.set_trace|breakpoint)\s*\(/i,
    extensions: ['.py', '.js', '.ts'],
    message: 'Debug code found',
    recommendation: 'Remove debug code before production',
  },
  {
    id: 'INSECURE_RANDOM', category: 'crypto',
    severity: 'medium',
    pattern: /\brandom\.(random|randint|choice|shuffle)\s*\(/i,
    extensions: ['.py'],
    message: 'Insecure random number generator',
    recommendation: 'Use the secrets module in security contexts',
  },
  {
    id: 'XXE', category: 'xxe', severity: 'high',
    pattern: /etree\.(parse|fromstring)\s*\([^)]*\)|xml\.dom\.minidom\.parse/i,
    extensions: ['.py'],
    message: 'XML parsing may allow XXE',
    recommendation: 'Disable external entities: XMLParser(resolve_entities=False)',
  },
];

const CODE_EXTENSIONS = new Set([
  '.py', '.js', '.cjs', '.mjs', '.ts', '.jsx', '.tsx', '.go',
  '.java', '.php', '.rb', '.yaml', '.yml', '.json',
]);
const DEFAULT_EXCLUDES = [
  '.git', 'node_modules', '__pycache__', '.venv', 'venv',
  'dist', 'build', '.tox', 'tests', 'test', '__tests__', 'spec',
];

function scanFile(filePath, rules) {
  const findings = [];
  const ext = path.extname(filePath).toLowerCase();
  let content;
  try { content = fs.readFileSync(filePath, 'utf-8'); } catch { return findings; }
  const lines = content.split('\n');

  for (const rule of rules) {
    const exts = rule.extensions;
    if (!exts.includes('*') && !exts.includes(ext)) continue;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const stripped = line.trim();
      const isComment = stripped.startsWith('#') ||
        stripped.startsWith('//') || stripped.startsWith('*') ||
        stripped.startsWith('/*');
      if (isComment) continue;
      const ruleDefRe = /^\s*(id|pattern|severity|message|recommendation|extensions|excludePattern|category)\s*:/;
      if (ruleDefRe.test(stripped)) continue;

      if (rule.pattern.test(line)) {
        rule.pattern.lastIndex = 0;
        if (rule.excludePattern && rule.excludePattern.test(line)) {
          rule.excludePattern.lastIndex = 0; continue;
        }
        findings.push({
          severity: rule.severity, category: rule.category,
          message: rule.message, file_path: filePath,
          line_number: i + 1,
          line_content: stripped.slice(0, 100),
          recommendation: rule.recommendation,
        });
      }
    }
  }
  return findings;
}

function walkDir(dir, excludeDirs) {
  const results = [];
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return results; }
  for (const entry of entries) {
    if (excludeDirs.includes(entry.name)) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) { results.push(...walkDir(full, excludeDirs)); }
    else if (entry.isFile()) {
      if (CODE_EXTENSIONS.has(path.extname(entry.name).toLowerCase())) {
        results.push(full);
      }
    }
  }
  return results;
}

function scanDirectory(scanPath, excludeDirs) {
  const resolved = path.resolve(scanPath);
  const findings = [];
  const files = walkDir(resolved, excludeDirs);
  for (const f of files) findings.push(...scanFile(f, SECURITY_RULES));
  findings.sort((a, b) =>
    (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9));
  const passed = !findings.some(
    f => f.severity === 'critical' || f.severity === 'high'
  );
  return { scan_path: resolved, files_scanned: files.length, passed, findings };
}

// --- shared helpers (inlined; keep in sync across verify-* scripts) ---

function parseCliArgs(argv, extraFlags) {
  const args = argv.slice(2);
  const result = { target: '.', verbose: false, json: false };
  if (extraFlags) Object.assign(result, extraFlags);
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '-v' || args[i] === '--verbose') result.verbose = true;
    else if (args[i] === '--json') result.json = true;
    else if (args[i] === '-h' || args[i] === '--help') result.help = true;
    else if (args[i] === '--exclude') {
      result.exclude = result.exclude || [];
      while (i + 1 < args.length && !args[i + 1].startsWith('-')) result.exclude.push(args[++i]);
    } else if (!args[i].startsWith('-')) result.target = args[i];
  }
  return result;
}

const SEP = '='.repeat(60);
const DASH = '-'.repeat(40);
const ICONS = {
  error: '✗', warning: '⚠', info: 'ℹ',
  critical: '\u{1F534}', high: '\u{1F7E0}', medium: '\u{1F7E1}', low: '\u{1F535}',
};

function buildReport(title, fields, issues, verbose, groupBy) {
  const lines = [SEP, title, SEP];
  for (const [k, v] of Object.entries(fields)) lines.push(`\n${k}: ${v}`);
  if (issues.length) {
    lines.push('\n' + DASH, 'Findings:', DASH);
    if (groupBy) {
      const groups = {};
      for (const i of issues) (groups[i[groupBy]] || (groups[i[groupBy]] = [])).push(i);
      for (const cat of Object.keys(groups).sort()) {
        const items = groups[cat];
        lines.push(`\n[${cat}] (${items.length})`);
        for (const i of items.slice(0, 10)) {
          lines.push(`  ${ICONS[i.severity] || 'ℹ'} ${i.file_path || ''}${i.line_number ? ':' + i.line_number : ''}`);
          lines.push(`    ${i.message}`);
          if (verbose && i.recommendation) lines.push(`    💡 ${i.recommendation}`);
        }
        if (items.length > 10) lines.push(`  ... and ${items.length - 10} more`);
      }
    } else {
      for (const i of issues) lines.push(`  ${ICONS[i.severity] || 'ℹ'} [${i.severity.toUpperCase()}] ${i.message}`);
    }
  }
  lines.push('\n' + SEP);
  return lines.join('\n');
}

function countBySeverity(issues, field) {
  const key = field || 'severity';
  const counts = {};
  for (const i of issues) counts[i[key]] = (counts[i[key]] || 0) + 1;
  return counts;
}

function formatReport(result, verbose) {
  const counts = countBySeverity(result.findings);
  const fields = {
    'Scan path': result.scan_path,
    'Files scanned': result.files_scanned,
    'Result': result.passed ? '✓ pass' : '✗ high-severity findings',
    'Counts': `critical: ${counts.critical || 0} | high: ${counts.high || 0}` +
      ` | medium: ${counts.medium || 0} | low: ${counts.low || 0}`,
  };
  return buildReport(
    'Security Scan Report', fields, result.findings, verbose, 'category'
  );
}

function main() {
  const opts = parseCliArgs(process.argv, { exclude: [] });
  if (opts.help) {
    console.log('Usage: security_scanner.cjs [path] [-v] [--json] [--exclude dir1 dir2]');
    process.exit(0);
  }
  const excludeDirs = [...DEFAULT_EXCLUDES, ...opts.exclude];
  const result = scanDirectory(opts.target, excludeDirs);

  if (opts.json) {
    console.log(JSON.stringify({
      scan_path: result.scan_path,
      files_scanned: result.files_scanned,
      passed: result.passed,
      counts: countBySeverity(result.findings),
      findings: result.findings,
    }, null, 2));
  } else {
    console.log(formatReport(result, opts.verbose));
  }
  process.exit(result.passed ? 0 : 1);
}

if (require.main === module) {
  main();
}

module.exports = { scanFile, SECURITY_RULES };

